<?php require __DIR__.'/../bootstrap.php';if(current_user())redirect('/dashboard/');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare("SELECT * FROM users WHERE (email=? OR username=?) AND status='active' LIMIT 1");$s->execute([post('identity'),post('identity')]);$u=$s->fetch();if($u&&password_verify((string)post('password'),$u['password_hash'])){if(!empty($u['must_reset_password'])){$raw=bin2hex(random_bytes(24));db()->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at,created_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR),NOW())')->execute([(int)$u['id'],hash('sha256',$raw)]);redirect('/reset-password/?token='.$raw);}login_user($u);redirect(($u['role']??'')==='admin'?'/admin/':'/dashboard/');}$msg='Invalid sign-in details.';}public_header('Login');?><section class="center-card"><span class="eyebrow">PocketCat workspace</span><h1>Welcome back</h1><p class="sub">Sign in to continue organizing your work.</p><?php if($msg):?><div class="flash error"><?=e($msg)?></div><?php endif;?><form method="post"><?=csrf_field()?><label>Email or Username<input name="identity" required></label><label>Password<input type="password" name="password" required></label><button class="btn full">Sign In</button></form><p><a href="/forgot-password/">Forgot password?</a> · <a href="/signup/">Create account</a></p></section><?php public_footer(); ?>